import inspect
from typing import List


def get_service_name_from_stack() -> str:
    """Get service - module name from stack."""
    stack = _get_modules_stack()
    module_name = ''
    for module_name in stack:
        if 'taf.ul.telemetry' not in module_name:
            break
    return module_name


def _get_modules_stack() -> List[str]:
    ret = []
    stack = inspect.stack(0)
    for frame_info in stack:
        module = inspect.getmodule(frame_info[0])
        if not module:
            continue
        module_name = module.__name__
        ret.append(module_name)
    return ret
